SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/974130947fcdb1b84376e825c816bafd1322500d/content/books/zizhi-tongjian/vol-294/year-0958/part-03/sources/library/jiuwudaishi-118-march-peace-gifts/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002783；EPUB电子本，纸本及异文待核", "id": "0ee064de-d661-5620-87f4-9b91cc1160af"}, {"title": "宋史·巻二百五十一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/974130947fcdb1b84376e825c816bafd1322500d/content/books/zizhi-tongjian/vol-294/year-0958/part-03/sources/library/songshi-251-murongyanzhao-family/source.txt", "note": "《宋史》巻二百五十一，段落 songshi-9c6e46fee832-p057267；EPUB电子本，纸本及异文待核", "id": "18c902ee-83ba-58c0-a3ca-7aaf242ba5dc"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/974130947fcdb1b84376e825c816bafd1322500d/content/books/zizhi-tongjian/vol-294/year-0958/part-03/sources/library/tongjian-294-958-peace-negotiations/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003487；电子底本待考，分段待核", "id": "699729ac-7fdb-5c95-8d60-44e0ce995e6f"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/974130947fcdb1b84376e825c816bafd1322500d/content/books/zizhi-tongjian/vol-294/year-0958/part-03/sources/library/tongjian-294-958-peace-settlement/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003488；电子底本待考，分段待核", "id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"title": "新五代史·卷六十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/974130947fcdb1b84376e825c816bafd1322500d/content/books/zizhi-tongjian/vol-294/year-0958/part-03/sources/library/xinwudaishi-62-jiangbei-settlement/source.txt", "note": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003154；EPUB电子本，纸本及异文待核", "id": "7c258e79-23d8-5e03-b061-26accc0b0d19"}, {"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8ed915b0f3bf92daf19318ca9962a9e6c2c54f00/content/books/zizhi-tongjian/vol-294/year-0958/part-01/sources/library/jiuwudaishi-118-march-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002782；EPUB电子本，纸本及异文待核", "id": "8af10a4a-0c69-5b2f-bbe1-167e16e440ad"}, {"title": "新五代史·卷六十七", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5b7d39c10017d28c66750d6a92a9b6db748131ef/content/books/zizhi-tongjian/vol-292/year-0956/part-03/sources/library/xinwudaishi-67-chenman-misidentifies/source.txt", "note": "《新五代史》卷六十七，段落 xin-wudaishi-b08f244b9241-p003376；EPUB电子本，纸本及异文待核", "id": "af34714e-89b9-5742-afa9-288c8dcd6168"}]'::jsonb)
