INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "慕容延钊", "aliases": ["慕容延釗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周殿前都虞候。958年率步骑与宋延渥水军循江进击南唐，奏报东㳍州获胜。《宋史》记父章领开州刺史，早年在郭威帐下、历供奉官及铁骑都虞候。生卒年未载。", "biography": null, "status": "draft", "id": "e30441c5-c329-5072-b247-0bf29eeb41df"}, {"name": "宋延渥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "洛阳人，950年任义成节度使，郭威南下时在滑州迎降。他的妻子是后晋石敬瑭的女儿永宁公主。迎降纪日两部史书有差异，生卒年未载。", "biography": null, "status": "draft", "id": "24f24435-a8b6-5d3e-9f40-ad0e7f494c03"}, {"name": "慕容章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "慕容延钊之父，《宋史》称其襄州马步军都校、领开州刺史。具体任官年代、生卒年未载。", "biography": null, "status": "draft", "id": "0f35afc9-b495-5531-887b-c329d9d8f7f3"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "刘承遇", "aliases": ["劉承遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐驻沅江都监。952年十月王逵等攻下沅江时被俘。生卒年未载。", "biography": null, "status": "draft", "id": "6377358b-b5f0-577c-960a-a256c9845699"}, {"name": "邵可迁", "aliases": ["邵可遷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越上直都指挥使、处州刺史。958年与路彦铢率四百战舰、万七千军士屯通州南岸。《新五代史》回述其常州败战时仍力战，子死于马前；各次军务不合为同一年同一战。生卒年未载。", "biography": null, "status": "draft", "id": "773dcbd3-a173-55c3-bf26-508c1e50e93d"}, {"name": "路彦铢", "aliases": ["路彥銖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越上直都指挥使。956年二月癸巳奉钱弘俶命进攻南唐宣州。生卒年未载。", "biography": null, "status": "draft", "id": "3af8f6aa-3cc5-5dc1-ad7c-665a3e802e03"}, {"name": "邵可迁子（姓名未载）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "邵可迁的儿子，姓名未载。《新五代史》记吴越军与柴克宏所领南唐军在常州作战时，死于父亲马前。与958年通州派舰是不同战役。", "biography": null, "status": "draft", "id": "83d81227-13da-5dd9-8932-ff8ac6abd8b2"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "高保融", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高从诲之子，荆南节度副使。948年十月父亲病重时，受命管理内外兵马事务；高从诲去世后，以留后身份暂掌军府。《新五代史》记他是高从诲的第三子。生卒年尚未确定。", "biography": null, "status": "draft", "id": "88e76c46-c48c-5103-9a49-99e0b54eed61"}, {"name": "赵匡赞", "aliases": ["趙匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵延寿的儿子。947年正月受耶律德光任命为护国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "ad59529e-c641-5bb7-bde5-3749239fd1d3"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
