SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "柴荣到迎銮，数次临江并遣水军击败南唐兵。", "citation": "卷294·显德五年（958年三月及相关追述）·zztj-v294-y0958-p017·原文件第22行", "note": "原文：辛卯，上如迎銮镇，屡至江口，遣水军击唐兵，破之。；核对说明：屡至为多次行动概述，不把全部出战都定辛卯一天。", "status": "draft", "id": "4e7cedf0-f423-55b0-b3ca-15872a6d3573", "subject_id": "f5fc0d01-500e-5043-bd92-c596361f9d88", "source_id": "699729ac-7fdb-5c95-8d60-44e0ce995e6f"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "958年三月辛卯到迎銮；多次临江与水战未独立纪日", "citation": "卷294·显德五年（958年三月及相关追述）·zztj-v294-y0958-p017·原文件第22行", "note": "原文：辛卯，上如迎銮镇，屡至江口，遣水军击唐兵，破之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "91408ae0-ac48-5b3a-8290-ada938cf63cd", "subject_id": "f5fc0d01-500e-5043-bd92-c596361f9d88", "source_id": "699729ac-7fdb-5c95-8d60-44e0ce995e6f"}, {"subject_table": "person", "field_path": "description", "claim_text": "柴荣：临迎銮江口，遣水军进攻。", "citation": "卷294·显德五年（958年三月及相关追述）·zztj-v294-y0958-p017·原文件第22行", "note": "原文：辛卯，上如迎銮镇，屡至江口，遣水军击唐兵，破之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "e5fea0d2-6870-52c9-a685-a692e1b3dab2", "subject_id": "697c1a4f-b373-5a78-8b47-330fe349a424", "source_id": "699729ac-7fdb-5c95-8d60-44e0ce995e6f"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：临迎銮江口，遣水军进攻。", "citation": "卷294·显德五年（958年三月及相关追述）·zztj-v294-y0958-p017·原文件第22行", "note": "原文：辛卯，上如迎銮镇，屡至江口，遣水军击唐兵，破之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "4640de47-e181-57eb-be67-bba28db252f5", "subject_id": "26f1ce74-07b8-5faa-864a-e3e2d9da9431", "source_id": "699729ac-7fdb-5c95-8d60-44e0ce995e6f"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同记辛卯到迎銮江口。", "citation": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002782；EPUB电子本，纸本及异文待核", "note": "原文：辛卯，幸迎鑾江口。；核对说明：江口巡临与后续各次水战分开。", "status"